// Role demos share the original prototype's sample records; no authentication is simulated.
let demoRole='reception',roleSection='home';
const identities={reception:['Amara Okafor','Receptionist','AO'],supervisor:['Chidi Nwosu','Supervisor','CN'],owner:['Ada Williams','Owner / Manager','AW']};
const activity=[{time:'08:45 WAT',actor:'Chidi Nwosu',action:'Room 203 remains blocked for maintenance.'},{time:'09:05 WAT',actor:'Chidi Nwosu',action:'Recorded reported cleaning completion for room 108.'},{time:'09:20 WAT',actor:'Chidi Nwosu',action:'Recorded reported cleaning completion for room 205.'}];
const work=[{room:'108',type:'Arrival preparation',at:'14:00 arrival',state:'Awaiting inspection',note:'Cleaning reported complete in person.'},{room:'205',type:'Arrival preparation',at:'16:00 arrival',state:'Awaiting inspection',note:'Cleaning reported complete in person.'},{room:'112',type:'Departure turnover',at:'Next arrival not assigned',state:'Cleaning in progress',note:'Work started and confirmed by supervisor.'}];
const requests=[{room:'120',title:'Fresh towels',note:'In-stay request · received 09:10',state:'Scheduled'},{room:'121',title:'Bathroom issue',note:'In-stay issue · received 09:25',state:'Needs assessment'}];
const staff=[{name:'Amara Okafor',role:'Receptionist',state:'Active'},{name:'Chidi Nwosu',role:'Supervisor',state:'Active'}];
const originalNav=$('.nav').innerHTML;
const style=document.createElement('style');style.textContent=`.owner-nav-group,.owner-operations{display:grid;gap:5px}.owner-operations{margin-top:24px;padding-top:8px;border-top:1px solid var(--line)}.owner-operations .nav-label{margin:12px 0 5px}#role-title:focus{outline:none}.role-picker{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--muted)}.role-picker select{min-height:34px;padding:5px 8px;width:153px;font-size:12px}.management-snapshot{display:grid;grid-template-columns:repeat(4,1fr);padding:26px 0;border-block:1px solid var(--line);margin-bottom:30px}.management-snapshot>div{padding:0 24px;border-right:1px solid var(--line)}.management-snapshot>div:first-child{padding-left:0}.management-snapshot>div:last-child{border:0}.management-snapshot strong{display:block;font:32px var(--display);margin:7px 0}.management-snapshot small{color:var(--muted)}.role-columns{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(280px,1fr);gap:28px}.decision-row{padding:22px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:20px}.decision-row:last-child{border:0}.decision-row p{font-size:13px;color:var(--muted);margin-top:4px}.decision-row button{margin-left:auto;white-space:nowrap}.decision-mark{width:38px;height:38px;display:grid;place-items:center;color:var(--gold);background:var(--sand);border-radius:50%;flex-shrink:0}.work-summary{padding:24px 28px;background:var(--forest);color:white;border-radius:var(--radius);margin-bottom:28px;display:flex;justify-content:space-between;align-items:center;gap:20px}.work-summary h2{font:25px var(--display)}.work-summary p{color:#d3dfd5;font-size:13px;margin-top:8px}.work-summary .totals{font-size:13px;color:#d3dfd5;display:flex;gap:28px;white-space:nowrap}.totals strong{font:30px var(--display);display:block;color:white}.work-card{padding:22px;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);margin-bottom:15px}.work-top{display:flex;justify-content:space-between;gap:15px}.work-top h3{font:25px var(--display)}.work-meta{display:flex;justify-content:space-between;gap:12px;margin:16px 0;color:var(--muted);font-size:12px}.work-bottom{display:flex;justify-content:space-between;align-items:center;gap:12px;padding-top:16px;border-top:1px solid var(--line)}.work-bottom small{color:var(--muted);max-width:55%}.audit-list{list-style:none;padding:0;margin:0}.audit-list li{padding:18px 0;border-bottom:1px solid var(--line)}.audit-list p{font-size:13px;margin:6px 0}.audit-list small{color:var(--muted);font-size:11px}.role-note{font-size:12px;color:var(--muted);margin:12px 0 20px}.role-table{overflow:auto}.role-actions{display:flex;gap:10px}.role-empty{padding:35px;text-align:center;color:var(--muted)}@media(max-width:1150px){.role-columns{grid-template-columns:1fr}.topbar{flex-wrap:wrap;height:auto;min-height:75px;padding-block:12px}.management-snapshot>div{padding-inline:16px}}@media(max-width:760px){.management-snapshot{grid-template-columns:repeat(2,1fr);gap:20px}.role-picker{flex-wrap:wrap}.top-actions{flex-wrap:wrap}.work-summary{display:block}.work-summary .totals{margin-top:20px}.decision-row{flex-wrap:wrap}.decision-row button{margin-left:0}}`;
document.head.append(style);
$('#guest-switch').insertAdjacentHTML('beforebegin','<div class="role-picker"><label for="demo-role">Demo view</label><select id="demo-role"><option value="reception">Receptionist</option><option value="supervisor">Supervisor</option><option value="owner">Owner / Manager</option><option value="guest">Guest</option></select></div>');
$('#guest-view').insertAdjacentHTML('afterend','<section id="role-view" hidden></section>');
function eventRecord(action){activity.push({private:roleSection==='team',time:new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Lagos',hour:'2-digit',minute:'2-digit'}).format(new Date())+' WAT',actor:identities[demoRole][0],action})}
function auditMarkup(){return '<ul class="audit-list">'+activity.filter(e=>demoRole==='owner'||!e.private).slice().reverse().map(e=>`<li><small>${esc(e.time)} · ${esc(e.actor)}</small><p>${esc(e.action)}</p></li>`).join('')+'</ul>'}
function counts(){return {occupied:bookings.filter(b=>['inhouse','departure'].includes(b.kind)).length,ready:roomData.filter(r=>r[2]==='Ready for check-in').length,waiting:work.filter(w=>w.state==='Awaiting inspection').length,progress:work.filter(w=>w.state==='Cleaning in progress').length}}
const baseSetPage=setPage;
setPage=function(next){if(demoRole==='owner'&&next==='housekeeping'){roleSection='work';renderRole();return}$('#role-view').hidden=true;baseSetPage(next);if(next==='guest')$('#demo-role').value='guest';else $('#demo-role').value=demoRole; if(demoRole==='owner'&&next!=='guest'){$('.profile small').textContent='Owner / Manager · Demo';document.querySelectorAll('[data-role-section]').forEach(b=>b.dataset.roleSection==='operations'?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current'))}};
syncOccupancy=function(){const c=counts(),preparing=24-c.occupied-c.ready-1;$('.occupancy p').innerHTML='<strong>'+c.occupied+' of 24 rooms occupied</strong> · '+Math.round(c.occupied/24*100)+'% occupancy';const values=[c.occupied,c.ready,preparing,1],names=['occupied','ready','being prepared','blocked'];values.forEach((v,i)=>{$('.legend').children[i].textContent=v+' '+names[i];$('.occupancy-line').children[i].style.width=v/24*100+'%'});const priority=$('[data-priority="inspection"]');priority.querySelector('.number').textContent=String(c.waiting).padStart(2,'0');priority.querySelector('small').textContent=c.waiting?'Supervisor or owner inspection needed':'No rooms awaiting inspection';document.querySelectorAll('.right-rail .task').forEach(el=>{const w=work.find(w=>w.room===el.querySelector('.room-no').textContent);if(w){el.querySelector('.badge').textContent=w.state;el.querySelector('.badge').classList.toggle('amber',w.state!=='Approved clean')}})};
function changeRole(role){if($('#modal').open)$('#modal').close();$('#toast').textContent='';if(role==='guest'){setPage('guest');return}demoRole=role;roleSection='home';$('#demo-role').value=role;$('.shell').classList.remove('guest-mode');const person=identities[role];$('.profile .avatar').textContent=person[2];$('.profile strong').textContent=person[0];$('.profile small').textContent=person[1]+' · Demo';$('.brand small').textContent=role==='owner'?'MANAGEMENT':role==='supervisor'?'HOUSEKEEPING':'OPERATIONS';$('.sidebar > .nav-label').textContent=role==='owner'?'Management':'Workspace';if(role==='reception'){$('.nav').innerHTML=originalNav;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>setPage(b.dataset.page));setPage('overview');return}const links=role==='owner'?[['home','Management Overview'],['finances','Financial Overview'],['team','Team'],['operations','Reception Operations'],['work','Cleaning & Inspections'],['requests','Service Requests'],['activity','Activity History']]:[['home','Cleaning & Inspections'],['requests','Service Requests'],['activity','Activity History']];const navButton=([key,label])=>`<button data-role-section="${key}">${label}</button>`;$('.nav').innerHTML=role==='owner'?`<div role="group" aria-label="Management priorities" class="owner-nav-group">${links.slice(0,3).map(navButton).join('')}</div><div class="owner-operations" role="group" aria-labelledby="owner-operations-label"><div id="owner-operations-label" class="nav-label">Hotel operations</div>${links.slice(3).map(navButton).join('')}</div>`:links.map(navButton).join('');document.querySelectorAll('[data-role-section]').forEach(b=>b.onclick=()=>{roleSection=b.dataset.roleSection;if(roleSection==='operations'){setPage('overview');return}renderRole()});renderRole()}
$('#demo-role').onchange=e=>changeRole(e.target.value);$('#guest-switch').onclick=()=>{if(page==='guest')changeRole(demoRole);else changeRole('guest')};
function roleHeading(title,description,action=''){return `<div class="heading"><div><h1 id="role-title" tabindex="-1">${title}</h1><p class="muted">${description}</p></div>${action}</div>`}
function renderRole(){page='role';$('#staff-view').hidden=true;$('#guest-view').hidden=true;$('#role-view').hidden=false;$('.demo-controls').hidden=true;$('#guest-switch').textContent='Guest experience ↗';document.querySelectorAll('[data-role-section]').forEach(b=>b.dataset.roleSection===roleSection?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current'));let html='';const owner=demoRole==='owner',c=counts();if(roleSection==='home'&&owner){html=roleHeading('Management Overview','Tuesday, 15 September 2026 · The hotel at a glance.')+`<section class="management-snapshot" aria-label="Hotel snapshot"><div><span>Rooms occupied</span><strong>${c.occupied}<span style="font:16px var(--body);color:var(--muted)"> / 24</span></strong><small>${Math.round(c.occupied/24*100)}% current occupancy</small></div><div><span>Ready rooms</span><strong>${c.ready}</strong><small>Vacant and approved clean</small></div><div><span>Collected today</span><strong>₦420,000</strong><small>Recorded payments · not revenue</small></div><div><span>Outstanding balances</span><strong>₦90,000</strong><small>Across 2 sample active stays</small></div></section><div class="role-columns"><section><div class="section-head"><h2>Decisions & exceptions</h2><span class="sample">Illustrative figures</span></div><div class="panel"><div class="decision-row"><span class="decision-mark">${c.waiting}</span><div><h3>Arrival rooms need inspection</h3><p>Personal inspection is required before approval.</p></div><button data-section="work">Review rooms</button></div><div class="decision-row"><span class="decision-mark">1</span><div><h3>Room 203 is unavailable</h3><p>Maintenance block · bathroom leak reported.</p></div><button id="owner-maintenance">View issue</button></div><div class="decision-row"><span class="decision-mark">1</span><div><h3>Payment awaits verification</h3><p>XYZ-2403 · confirm through the hotel’s process.</p></div><button data-section="finances">Review payment</button></div></div></section><aside><div class="section-head"><h2>Recent activity</h2><button class="quiet" data-section="activity">View history</button></div>${auditMarkup()}<div class="handover"><h3>Service requests</h3><p>${requests.filter(r=>r.state!=='Completed').length} open requests need coordination.</p><button class="quiet" data-section="requests">Review requests ↗</button></div></aside></div>`}
else if(roleSection==='home'||roleSection==='work'){html=roleHeading('Cleaning & Inspections','Coordinate the work. Personally verify the result.')+`<section class="work-summary"><div><h2>Ready begins with a real inspection.</h2><p>Cleaners report to you in person. Record only work you have confirmed.</p></div><div class="totals"><div><strong>${c.waiting}</strong>awaiting inspection</div><div><strong>${c.progress}</strong>in progress</div></div></section><div class="role-columns"><section><div class="section-head"><h2>Room preparation queue</h2><span class="muted">3 sample tasks</span></div>${work.map(w=>`<article class="work-card"><div class="work-top"><div><h3>Room ${w.room}</h3><span class="muted">${w.type}</span></div><span class="badge ${w.state==='Needs attention'?'red':w.state==='Awaiting inspection'?'amber':''}" style="align-self:start">${w.state}</span></div><div class="work-meta"><span>${w.at}</span><span>${w.room==='112'?'Turnover':'Pre-arrival'}</span></div><div class="work-bottom"><small>${esc(w.note)}</small><button data-work="${w.room}" ${w.state==='Approved clean'?'':'class="primary"'}>${w.state==='Awaiting inspection'?'Record inspection':w.state==='Approved clean'?'View inspection':'Update progress'}</button></div></article>`).join('')}</section><aside><h2>Keep in view</h2><section class="handover"><span class="badge red">Maintenance block</span><h3 style="margin-top:15px">Room 203 · Bathroom leak</h3><p>Keep this room unavailable. Cleaning approval does not clear a maintenance block.</p><button id="supervisor-maintenance">View issue</button></section><div style="margin-top:28px"><div class="section-head"><h2>Service requests</h2><button class="quiet" data-section="requests">View all ↗</button></div>${requests.map(r=>`<div class="task"><span class="room-no">${r.room}</span><div><p>${r.title}</p><span class="badge amber">${r.state}</span></div></div>`).join('')}</div><p class="role-note">Guest billing and staff access settings are outside the supervisor’s workspace.</p></aside></div>`}
else if(roleSection==='activity'){html=roleHeading('Activity History','An attributable record of operational updates.')+`<section class="panel" style="padding:8px 26px">${auditMarkup()}</section><p class="role-note">Illustrative history. New demo actions use the current WAT time; no permanent audit record is stored.</p>`}
else if(roleSection==='requests'){html=roleHeading('Service Requests','Coordinate relevant room work without exposing guest financial information.')+requests.map((r,i)=>`<article class="work-card"><div class="work-top"><div><h3>Room ${r.room} · ${r.title}</h3><p class="muted">${r.note}</p></div><span class="badge">${r.state}</span></div><div class="work-bottom" style="margin-top:20px"><small>Record progress after confirming the work in person.</small><button data-request="${i}" ${r.state==='Completed'?'disabled':''}>${r.state==='Completed'?'Completed':'Update request'}</button></div></article>`).join('')}
else if(roleSection==='finances'){html=roleHeading('Financial Overview','Recorded collections, balances and exceptions. All figures are illustrative.')+`<section class="management-snapshot"><div><span>Collected today</span><strong>₦420,000</strong><small>Payments recorded</small></div><div><span>Outstanding</span><strong>₦90,000</strong><small>2 active stays</small></div><div><span>Pending verification</span><strong>₦60,000</strong><small>Excluded from collections</small></div><div><span>Refund exception</span><strong>1</strong><small>Accountant-managed</small></div></section><section class="panel role-table"><table><caption style="text-align:left;padding:20px;font-size:18px;font-weight:600">Items to follow up</caption><thead><tr><th scope="col">Record</th><th scope="col">Amount</th><th scope="col">Status</th><th scope="col">Next step</th></tr></thead><tbody><tr><td>XYZ-2403<small>Sarah Bello</small></td><td>₦60,000</td><td><span class="badge amber">Verification pending</span></td><td>Reception verifies payment</td></tr><tr><td>XYZ-2398<small>Aisha Yusuf</small></td><td>₦50,000</td><td><span class="badge amber">Balance due</span></td><td>Review at departure</td></tr><tr><td>XYZ-2399<small>James Udo</small></td><td>₦40,000</td><td><span class="badge amber">Balance due</span></td><td>Review at departure</td></tr><tr><td>PAY-DEMO-07<small>Payment without confirmed booking</small></td><td>₦75,000</td><td><span class="badge red">Refund exception</span></td><td><button id="refund-details">View process</button></td></tr></tbody></table></section><p class="role-note">Collections do not imply earned revenue or profit. Refund execution stays with the accountant’s existing process; timing and verification procedures remain to be agreed.</p>`}
else if(roleSection==='team'){html=roleHeading('Team','Named staff profiles with responsibilities assigned by the owner.','<button class="primary" id="invite-staff">Draft staff invitation</button>')+`<section class="panel role-table"><table><thead><tr><th scope="col">Team member</th><th scope="col">Role</th><th scope="col">Access</th><th scope="col">Action</th></tr></thead><tbody>${staff.map((s,i)=>`<tr><td><strong>${s.name}</strong></td><td>${s.role}</td><td><span class="badge ${s.state==='Disabled'?'amber':''}">${s.state}</span></td><td><button data-staff="${i}">${s.state==='Active'?'Review access':'Restore demo access'}</button></td></tr>`).join('')}</tbody></table></section><section class="handover" style="margin-top:24px"><h3>Work is always attached to a person</h3><p>Disabling an account preserves its historical actions. Cleaners work in person and do not need accounts. The accountant’s refund process does not introduce an accountant app role.</p></section>`}
$('#role-view').innerHTML=html;$('#breadcrumb').textContent=$('#role-title').textContent;document.title='XYZ Hotel · '+$('#role-title').textContent;$('#role-title').focus();document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{roleSection=b.dataset.section;roleSection==='operations'?setPage('overview'):renderRole()});document.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>workDialog(b.dataset.work));document.querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>requestDialog(Number(b.dataset.request)));document.querySelectorAll('[data-staff]').forEach(b=>b.onclick=()=>staffDialog(Number(b.dataset.staff)));['owner-maintenance','supervisor-maintenance'].forEach(id=>{if($('#'+id))$('#'+id).onclick=()=>openDialog('Room 203 · Maintenance issue','<span class="badge red">Unavailable</span><p style="margin-top:20px">Bathroom leak reported by the supervisor. Maintenance resolution must be confirmed through the hotel’s process before the room can be released.</p><p class="role-note">The block remains in place in this demo.</p>')});if($('#refund-details'))$('#refund-details').onclick=()=>openDialog('Refund exception','<p>The accountant handles this refund through the hotel’s existing process.</p><div class="notice" style="margin-top:20px">A payment was taken without a confirmed booking. No refund has been executed or verified in this demo.</div><p>Refund timing, verification and tracking are still open policy decisions. Customer care supports the guest through the agreed contact channels.</p>');if($('#invite-staff'))$('#invite-staff').onclick=inviteDialog}
function workDialog(room){if(!['supervisor','owner'].includes(demoRole))return;const w=work.find(w=>w.room===room);if(w.state==='Approved clean'){openDialog('Room '+room+' · Inspection record',`<span class="badge">Approved clean</span><p style="margin-top:18px">${esc(w.note)}</p><p class="role-note">Occupancy and maintenance are evaluated separately from cleanliness.</p>`);return}const inspection=w.state==='Awaiting inspection';openDialog('Room '+room+' · '+(inspection?'Record inspection':'Update progress'),`<p class="muted">${w.type} · ${w.state}</p><p class="role-note">Recording as ${identities[demoRole][0]} · ${identities[demoRole][1]}</p><form id="work-form"><div class="field"><label for="work-outcome">${inspection?'Inspection outcome':'Confirmed progress'}</label><select id="work-outcome">${inspection?'<option value="Approved clean">Approve as clean</option><option value="Needs attention">Needs attention · request rework</option>':w.state==='Cleaning in progress'?'<option value="Awaiting inspection">Cleaner reported work complete</option><option value="Blocked">Record a blocker</option>':'<option value="Cleaning in progress">Confirm work has resumed</option>'}</select></div><div class="field"><label for="work-note">${inspection?'Inspection notes':'Progress notes'} (required)</label><textarea id="work-note" rows="3" required></textarea></div><div class="check"><input id="work-confirm" type="checkbox" required><label for="work-confirm">${inspection?'I personally inspected this room and this outcome reflects what I found.':'I confirmed this update in person. Reported completion is not cleanliness approval.'}</label></div><div class="dialog-actions"><button type="submit" class="primary" id="save-work" disabled>Record ${inspection?'inspection':'progress'}</button></div></form>`);$('#work-confirm').onchange=e=>$('#save-work').disabled=!e.target.checked;$('#work-form').onsubmit=e=>{e.preventDefault();const note=$('#work-note').value.trim();if(!note){$('#work-note').setCustomValidity('Enter a note about the work.');$('#work-note').reportValidity();return}const outcome=$('#work-outcome').value;w.state=outcome;w.note=note+' · '+identities[demoRole][0];const r=roomData.find(r=>r[0]===room);r[2]=outcome==='Approved clean'?'Ready for check-in':outcome;r[3]=outcome==='Approved clean'?'Vacant · Approved clean':'Vacant · '+outcome;const b=bookings.find(b=>b.room===room&&b.kind==='arrival');if(b)b.state=outcome==='Approved clean'?(b.paid?'Ready for check-in':'Payment to verify'):outcome;eventRecord('Room '+room+': '+outcome+'. '+note);syncOccupancy();if(room==='108'){$('.timeline').lastElementChild.innerHTML='<strong>'+(outcome==='Approved clean'?'Room ready for check-in':outcome==='Awaiting inspection'?'Your room is being checked':'Preparing for your arrival')+'</strong><small>'+(outcome==='Approved clean'?'Reception will guide you through the arrival procedure.':'The hotel is preparing your room. Reception will confirm when it is ready.')+'</small>'}$('#modal').close();renderRole();notify('Room '+room+' updated · attributed to '+identities[demoRole][0])};$('#work-note').oninput=()=>$('#work-note').setCustomValidity('')}
function requestDialog(i){const r=requests[i];openDialog('Room '+r.room+' · '+r.title,`<form id="request-form"><p class="muted">Current status: ${r.state}</p><div class="field" style="margin-top:20px"><label for="request-update">Confirmed update</label><select id="request-update"><option>In progress</option><option>Completed</option></select></div><div class="check"><input id="request-confirm" type="checkbox" required><label for="request-confirm">I confirmed this service update in person.</label></div><div class="dialog-actions"><button class="primary">Record update</button></div></form>`);$('#request-form').onsubmit=e=>{e.preventDefault();r.state=$('#request-update').value;eventRecord('Room '+r.room+' '+r.title+': '+r.state+'.');$('#modal').close();renderRole();notify('Service request updated in the demo')}}
function staffDialog(i){const s=staff[i];openDialog(s.name+' · Access',`<p>${s.role} · ${s.state}</p><div class="notice" style="margin-top:20px">This changes only the sample access record. Historical actions keep their original attribution. The demo role selector remains available for design review.</div><button class="primary" id="confirm-access">${s.state==='Active'?'Disable demo access':'Restore demo access'}</button>`);$('#confirm-access').onclick=()=>{s.state=s.state==='Active'?'Disabled':'Active';eventRecord(s.name+': demo access '+s.state.toLowerCase()+'.');$('#modal').close();renderRole();notify('Sample access record updated')}}
function inviteDialog(){openDialog('Draft staff invitation','<form id="invite-form"><div class="field"><label for="staff-name">Employee full name</label><input id="staff-name" required></div><div class="field"><label for="staff-email">Employee email</label><input id="staff-email" type="email" required></div><div class="field"><label for="staff-role">Assigned role</label><select id="staff-role"><option>Receptionist</option><option>Supervisor</option></select></div><p class="role-note">Preview only. No account is created and no invitation is sent.</p><div class="dialog-actions"><button class="primary">Review invitation</button></div></form>');$('#invite-form').onsubmit=e=>{e.preventDefault();$('#dialog-body').innerHTML=`<h3>Invitation draft</h3><p style="margin-top:16px">${esc($('#staff-name').value)} · ${esc($('#staff-role').value)}</p><p>${esc($('#staff-email').value)}</p><div class="notice" style="margin-top:20px">Not sent. In the connected product, this employee would set their own password.</div>`;$('#close-modal').focus()}}
// Keep the role picker available for exploring, clearly outside real access control.
$('#about').onclick=()=>openDialog('About this prototype','<p><strong>Approved skeletal framework.</strong> This is a starting point to build upon, not a final design decision.</p><p style="margin-top:16px">Explore Receptionist, Supervisor, Owner / Manager and Guest using the Demo view selector.</p><p class="role-note">This selector is for design review, not staff authentication. All records and changes are local samples and reset on reload.</p>');
document.addEventListener('click',e=>{if(e.target.id==='checkin'&&!e.target.disabled){eventRecord('Completed demo check-in for '+$('#dialog-title').textContent+'.')}},true);
changeRole('owner');
